// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "sudicideAnyone should revert for non-owner");
    }
}
